SELECT * FROM (SELECT e.event_id,'DIM:'||s.inspection_id case_id,e.activity,e.timestamp FROM (SELECT 'DIM:'||inspection_id event_id,'Dimensional Inspection Completed' activity,inspected_at timestamp,inspection_id source_key FROM dimension_inspection WHERE inspected_at IS NOT NULL AND (1=1)) e JOIN dimension_inspection s ON s.inspection_id=e.source_key) ORDER BY case_id,timestamp,event_id;
